INSERT INTO team_match_stats VALUES(16284988,'LIV','2026-08-09',NULL,NULL,15,14,6,8,2,3,431,399,NULL,23,NULL,21,NULL,3,0,4,53.0,9,8,'4-2-3-1','4-4-2','sofascore / [2026-08-15 프리시즌 보강] FotMob /api/data/matchDetails + /api/data/teams (실제 Chrome 경유 수집 2026-08-15)',unistr('measured / measured / ⚠️ 원천은 SofaScore가 아니라 **FotMob**이다 — 같은 테이블의 기존 SofaScore 행과 provenance가 다르다. ⛔ **xG는 FotMob이 친선에 제공하지 않는다**(스탯 그룹 자체에 없음) — 이 행들의 xg_v/xg_o는 NULL이며 0이 아니다. ⛔ **PPDA도 산출 불가** — WhoScored가 클럽 친선을 커버하지 않아(픽스처 44건 전부 공식전) Opta 이벤트 원천이 없다. / ⚠️ [2026-08-15 정정] xg_v/xg_o를 **0.0 → NULL**로 바꿨다. 0.0은 측정값이 아니라 미제공이다 —\u000a   FotMob은 친선에 xG 항목 자체를 두지 않고, SofaScore는 403이며, ESPN·Sky·리버풀 공식·TIA 어느 매치리포트에도 xG가 없고 Understat은 친선 미커버다.\u000a   2-3 경기에서 양팀 xG 0은 거짓 신호를 준다.'),NULL,NULL,NULL,NULL,NULL,NULL,NULL,8,12,4,12,6,12,5,11,12,12,10,17,10,8,NULL,NULL,NULL,NULL);
INSERT INTO team_match_stats VALUES(16260286,'AVL','2026-08-12',2.129999999999999894,1.030000000000000026,15,12,4,6,5,3,368,588,36,23,54,30,14,6,2,0,43.0,13,11,'4-2-3-1','4-3-3','SofaScore API event/lineups/statistics/incidents/average-positions + player heatmap/statistics (collected 2026-08-13) / [2026-08-14 xG 보충] beIN Sports 2026-08-12 ''Emery hails Villa''s young lions'' https://www.beinsports.com/en-us/soccer/uefa-super-cup/articles/emery-hails-villas-young-lions-after-super-cup-defeat-to-psg-2026-08-12 / [2026-08-14 마이그레이션 015] PPDA=WhoScored matchCentreData(Opta) 이벤트 산출 · 경합/수비 지표=FotMob matchDetails matchId=5729447 (WhoScored 이벤트 집계로 교차검증)','measured / ⚠️ **xg_v/xg_o는 실측이 아니라 보도값이다.** SofaScore 원천이 0.0으로 비어 있어(수집 실패) beIN Sports가 전한 **에메리 본인 인용 수치 2.13 : 1.03**으로 채웠다. 나머지 필드(슈팅·패스·듀얼 등)는 SofaScore 실측이므로 **이 두 값만 provenance가 다르다** — 집계·비교 시 구분할 것. 교차확인 시도했으나 검색되는 동일 수치가 전부 같은 beIN 출처 기반이라 **독립 검증은 되지 않았다**. SofaScore/Opta 원천이 확보되면 덮어쓸 것. / ⚠️ PPDA·경합·수비 지표는 SofaScore가 아니라 WhoScored(Opta)·FotMob 원천이다 — 같은 행의 SofaScore 필드와 provenance가 다르다. / 교차검증 결과: 태클 18·인터셉트 6·클리어 13·공중볼 승리 4는 WhoScored 이벤트 집계와 **정확히 일치**. 공중볼 시도 12는 FotMob 승률 33%에서 역산했고 WhoScored 집계와도 일치한다. / ⚠️ **드리블 시도만 두 원천이 갈린다** — FotMob 승률 59%로 역산하면 17이고 WhoScored TakeOn 이벤트 집계는 19다(성공 10은 양쪽 동일). 정의 차이(무산 시도의 분류)로 보이며, 팀 단위 블록의 원천 일관성을 위해 **FotMob 값 17을 채택**했다. 선수별 원천값은 player_matches.stats_json.whoscored에 있다.',12.58999999999999986,8.5,428,34,289,34,'분자=상대가 자기 진영 3/5(x<60)에서 시도한 패스 · 분모=해당 팀 수비액션(Tackle·Interception·Challenge·Foul) 상대 진영 2/5(x>40). 원천=WhoScored matchCentreData(Opta) 이벤트 1588건, 2026-08-14 수집. ⚠️ PPDA는 구현마다 존 경계·액션 종류가 다르다 — 이 정의와 다른 출처의 PPDA를 직접 비교하지 말 것.',4,12,8,12,10,17,14,21,18,23,6,9,13,28,NULL,NULL,NULL,NULL);
